if not os.path.exists(P): fail(P + ' 파일을 못 찾았어요. privacy_policy.html이 있는 프로젝트 맨 위 폴더에서 실행해 주세요')
raw = open(P, 'rb').read().decode('utf-8')
crlf = '\r\n' in raw
s = raw.replace('\r\n', '\n')
if 'Google AdMob' in s:
    print('이미 적용돼 있어요'); sys.exit(0)

def one(t, old, new, L, name):
    n = t.count(old)
    if n != 1: fail(f'{L} · {name} — 넣을 자리가 1곳이어야 하는데 {n}곳이에요')
    return t.replace(old, new)

done = 0
for L, (SUM, S1a, S1b, DT, DD, S4P, ADI, ADP, BNN, BNI, BNP, BOX, S5a, S5b, S10, META) in T.items():
    start = s.find(f'<article class="doc" data-lang="{L}"')
    if start < 0: fail(f'{L} 언어 부분을 못 찾았어요')
    end = s.index('</article>', start)
    t = s[start:end]
    kv = re.search(r'<div class="kv"><span>(.*?)</span><p>.*?</p><span>(.*?)</span>', t)
    if not kv: fail(f'{L} · 4번 카드 모양을 못 찾았어요')
    K1, K2 = kv.groups()
    # 한눈에 보기
    t = one(t, '</ul></section><nav class="toc"', f'<li>{SUM}</li></ul></section><nav class="toc"', L, '한눈에 보기')
    # 1번: 외부로 가는 정보
    t = one(t, '</ul><div class="box">', f'<li>{S1a}</li><li>{S1b}</li></ul><div class="box">', L, '1번 목록')
    # 2번: 권한
    t = one(t, f'</dl></section><section class="sec" id="{L}-s3">',
            f'<div><dt>{DT}</dt><dd>{DD}</dd></div></dl></section><section class="sec" id="{L}-s3">', L, '2번 권한')
    # 4번: 설명 문장
    m = re.search(rf'(id="{L}-s4"><h2>.*?</h2><p>)(.*?)(</p>)', t)
    if not m: fail(f'{L} · 4번 설명 문장을 못 찾았어요')
    t = t[:m.start(2)] + S4P + t[m.end(2):]
    # 4번: 카드 2개 + 맞춤 광고 안내
    cards = (f'<div class="svc-i"><b>Google AdMob</b><div class="kv"><span>{K1}</span><p>{ADI}</p><span>{K2}</span><p>{ADP}</p></div></div>'
             f'<div class="svc-i"><b>{BNN}</b><div class="kv"><span>{K1}</span><p>{BNI}</p><span>{K2}</span><p>{BNP}</p></div></div>')
    t = one(t, '</div><div class="box">', cards + '</div><div class="box">', L, '4번 카드')
    t = one(t, f'</section><section class="sec" id="{L}-s5">', f'<div class="box">{BOX}</div></section><section class="sec" id="{L}-s5">', L, '4번 안내')
    # 5번: 보관 기간
    t = one(t, f'</ul></section><section class="sec" id="{L}-s6">', f'<li>{S5a}</li><li>{S5b}</li></ul></section><section class="sec" id="{L}-s6">', L, '5번 보관')
    # 10번: 개정 이력 (맨 위에)
    i = t.find(f'id="{L}-s10">')
    j = t.find('<ul><li>', i)
    if i < 0 or j < 0: fail(f'{L} · 10번 개정 이력을 못 찾았어요')
    t = t[:j] + f'<ul><li>{S10}</li><li>' + t[j + len('<ul><li>'):]
    # 맨 위 최종 수정 날짜
    mm = re.search(r'(<div class="meta"><span>.*?</span><span>)(.*?)(</span>)', t)
    if not mm: fail(f'{L} · 최종 수정 날짜를 못 찾았어요')
    t = t[:mm.start(2)] + META + t[mm.end(2):]
    s = s[:start] + t + s[end:]
    done += 1
    print('✔', L)

if done != 22: fail(f'22개 언어여야 하는데 {done}개만 바꿨어요')
open(P, 'wb').write((s.replace('\n', '\r\n') if crlf else s).encode('utf-8'))
print('저장했어요. (22개 언어)')
